/* POLISH: scoped to audited legacy/utility surfaces; mature scenes are untouched. */
#panels .cookbook-list{display:grid;grid-auto-rows:max-content;align-content:start;overflow-y:auto}
#panels .cookbook-list .cookbook-card{height:auto;min-height:180px;flex-shrink:0;overflow:visible;padding:10px 7px}
#panels .cookbook-card-art{height:76px;min-height:76px;flex-shrink:0}
