import fs from 'node:fs/promises';
import {createRequire} from 'node:module';
import {spawn} from 'node:child_process';
import crypto from 'node:crypto';
import * as E from './web/engine.js';
const out='artifacts/kitchen-concept-remaster-20260927';
await fs.mkdir(out+'/references',{recursive:true});
const hashes={}; async function walk(d){for(const e of await fs.readdir(d,{withFileTypes:true})){const p=d+'/'+e.name;if(e.isDirectory())await walk(p);else hashes[p]=crypto.createHash('sha256').update(await fs.readFile(p)).digest('hex');}}for(const d of ['web','assets','core','data','tools'])await walk(d);
await fs.writeFile(out+'/source-before.json',JSON.stringify(hashes));
const {chromium}=createRequire(import.meta.url)(process.env.APPDATA+'/npm/node_modules/gsd-pi/node_modules/playwright-core');
const server=spawn(process.execPath,['server.mjs','0'],{stdio:['ignore','pipe','pipe'],windowsHide:true});let browser;
try{const url=await new Promise((r,j)=>{server.on('error',j);server.stdout.on('data',b=>{const m=String(b).match(/http:\\/\\/127\\.0\\.0\\.1:\\d+/);if(m)r(m[0]);});});browser=await chromium.launch({headless:true});const report={url,viewport:{width:390,height:844},isolated:true,screens:[],errors:[]};
for(let lv=0;lv<4;lv++){
 const at=Date.now(),s=E.freshState(at,2718);s.progress.tutorialSeen=true;s.cp=1280;s.kitchenLevel=lv;E.startBatch(s,0,at);const context=await browser.newContext({viewport:report.viewport,reducedMotion:'reduce'});
 await context.addInitScript(({s,at})=>{Date.now=()=>at;if(location.protocol==='http:')localStorage.setItem('chick-kitchen-v1',JSON.stringify(s));},{s,at});const page=await context.newPage();page.on('pageerror',e=>report.errors.push(e.message));await page.goto(url);await page.locator('[data-control-id=\"start\"]').click();await page.waitForTimeout(800);await page.evaluate(()=>document.fonts.ready);await page.screenshot({path:"'`${out}/references/runtime-kitchen-lv${lv+1}.png`});report.screens.push({level:lv+1,controls:await page.locator('"'button').evaluateAll(es=>es.map(e=>({text:e.textContent,aria:e.getAttribute('aria-label'),id:e.getAttribute('data-control-id')})))});await context.close();
}
await fs.writeFile(out+'/runtime-evidence.json',JSON.stringify(report,null,2));console.log(JSON.stringify(report));
}finally{await browser?.close();server.kill();}
